    15	function transformDecimalAndSpaceToAscii(s) {
    16	  let out = '';
    17	
    18	  for (const ch of codePoints(s)) {
    19	    if (isUnicodeWhitespace(ch)) {
    20	      out += ' ';
    21	      continue;
    22	    }
    23	    const value = decimalDigitValue(ch.codePointAt(0));
