  1	// A focused reimplementation of argparse.ArgumentParser, covering the parts
  2	// this CLI exercises: required value-taking long options with a type
  3	// converter, the automatic -h/--help action, prefix abbreviation, and
  4	// argparse's exact error text and exit codes.
  5	
  6	import { SystemExit } from './exit.mjs';
  7	import { formatHelp, formatUsage } from './formatter.mjs';
  8	import { strRepr } from '../pyrepr.mjs';
  9	
 10	// argparse's own test for "looks like a negative number rather than a flag".
 11	const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;
 12	
 13	export class ArgumentParser {
 14	  constructor({ prog }) {
 15	    this.prog = prog;
 16	    this.actions = [];
 17	
 18	    this.addArgument(['-h', '--help'], {
 19	      action: 'help',
 20	      help: 'show this help message and exit',
 21	    });
 22	  }
